async function submitErrorAction(e:React.FormEvent){e.preventDefault();if(!errorAction)return;setBusy(true);setErrorActionError('');try{await api('jobs/'+encodeURIComponent(errorAction.id)+'/resolve','POST',{action:errorActionKind,confirm:true});setErrorAction(null);setDetails(null);setNotice('Requested action queued. Original scan history is preserved.');await refresh(false)}catch(e){setErrorActionError(String(e).replace(/^Error: /,''))}finally{setBusy(false)}}
