function archiveFields(advanced:boolean){return [['maxDepth','Maximum archive layers',1,20,1,'Outer archive is layer 1. TAR.GZ uses 2 layers; maximum 20.'],['maxFiles','Maximum archive entries',10,100,1,'Total entries allowed inside an archive, including nested archives. Default: 10; choose up to 100.'],['maxBytes','Maximum total expanded size (GB)',0.000001,100,1e9,'Total disk space allowed for unpacked contents. Default: 10 GB across all layers.'],['maxEntryBytes','Maximum size per extracted file (GB)',0.000001,100,1e9,'Limits each individual file unpacked from an archive. Example: 2 GB allows each extracted file to be up to 2 GB. Keep this at or below the total expanded-size budget. If any file exceeds it, inspection is incomplete and the archive follows scan-failed handling.'],['maxRatio','Maximum expansion ratio',1,10000,1,'Total expanded bytes divided by original archive bytes; also checked per ZIP member.'],['seconds','Extraction time limit (seconds)',1,3600,1,'Wall and CPU limits apply to extraction; the job timeout bounds all member scans.'],['concurrency','Simultaneous archive inspections',1,2,1,'Within profile/global worker limits; maximum 2 archive inspections across this instance.']].filter(([key])=>advanced?!['maxFiles','maxBytes'].includes(String(key)):['maxFiles','maxBytes'].includes(String(key))).map(([key,label,min,max,scale,help])=><label className="field" key={String(key)}>{String(label)}<input type="number" min={Number(min)} max={Number(max)} step={Number(scale)===1?'1':'any'} required value={Number(draft.archive?.[String(key)]||0)/Number(scale)} onChange={e=>setDraft({...draft,archive:{...draft.archive,[String(key)]:Math.round(Number(e.target.value)*Number(scale))}})}/><small>{String(help)}</small></label>)}
function validateProfileStep(all=false,beforeStep?:number){const form=profileForm.current;if(!form)return true;const controls=Array.from(form.querySelectorAll<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>('input,select,textarea'));const invalid=controls.find(el=>el.willValidate&&(all||(beforeStep===undefined?el.closest('[data-profile-step]')?.getAttribute('data-profile-step')===String(profileStep):Number(el.closest('[data-profile-step]')?.getAttribute('data-profile-step'))<beforeStep))&&!el.checkValidity());if(!invalid)return true;const target=Number(invalid.closest('[data-profile-step]')?.getAttribute('data-profile-step')||0);setProfileStep(target);const disclosure=invalid.closest('details');if(disclosure)disclosure.open=true;requestAnimationFrame(()=>{invalid.scrollIntoView({block:'center'});invalid.reportValidity()});return false}
