async function browse(marker=''){if(!mountID)return;setBusy(true);setError('');try{const v=await api(`mounts/${mountID}/files?prefix=${encodeURIComponent(prefix)}&marker=${encodeURIComponent(marker)}`);setBlobs(marker?[...blobs,...v.files]:v.files);setNext(v.nextMarker);if(!marker)setSelected([])}catch(e){setError(String(e).replace(/^Error: /,''))}finally{setBusy(false)}}
